  ('calf-raise', 'legs', 'Single-Leg Calf Raise', 'Calf Raise', 'Single-leg', 'reps', true, array['box'], array['calves'], '{}', array['abs'], 'On the edge of a step, lower the heel fully and rise onto the ball of the foot.', array['Full stretch at the bottom.', 'Rise as high as possible.', 'Fingertips on a wall for balance only.'], array['Bouncing.', 'Partial range.'], null, 'Full range, no bounce.', 3, 10, 20, 45),
