  ('hip-90-90', 'mobility', '90/90 Hip Switch', '90/90', 'Preparation', 'reps', false, array['floor'], array['glutes', 'adductors'], array['hip_flexors', 'obliques'], '{}', 'Seated with both knees bent to 90°, rotate the knees from one side to the other.', array['Sit tall.', 'Keep both feet planted and pivot on the heels.', 'Use the hands as little as possible.'], array['Collapsing the chest.', 'Forcing the knees down.'], null, null, 2, 8, 12, 15),
  ('worlds-greatest-stretch', 'mobility', 'Lunge with Rotation', 'Lunge Rotation', 'Preparation', 'reps', true, array['floor'], array['hip_flexors', 'adductors'], array['hamstrings', 'obliques', 'mid_back'], '{}', 'A deep lunge with the elbow lowered to the instep, followed by a reach to the ceiling.', array['Long lunge; back leg straight.', 'Sink the hips, then rotate from the upper back.', 'Follow the hand with the eyes.'], array['Front knee collapsing inward.', 'Twisting from the lower back.'], null, null, 2, 4, 6, 15),
  ('deep-squat-hold', 'mobility', 'Deep Squat Hold', 'Deep Squat', 'Flexibility', 'hold', false, array['floor'], array['adductors', 'glutes'], array['calves', 'lower_back'], '{}', 'Rest in the bottom of a squat with the heels down.', array['Heels flat, feet a little wider than the hips.', 'Elbows inside the knees, chest lifted.', 'Relax and breathe.'], array['Heels lifting.', 'Feet turned out very far to find depth.'], null, 'Heels down, hips below knees, no support.', 3, 30, 90, 30),
  ('toe-touch', 'mobility', 'Standing Toe Touch', 'Toe Touch', 'Flexibility', 'hold', false, array['floor'], array['hamstrings'], array['calves', 'lower_back'], '{}', 'Fold forward from the hips with straight legs until the fingertips rest on the floor.', array['Legs straight; quads on.', 'Hinge from the hips first.', 'Exhale and let the spine hang.'], array['Bending the knees to reach.', 'Bouncing.'], null, 'Fingertips on the floor, knees locked.', 3, 20, 45, 20),
